import { Injectable, inject } from '@angular/core';
import { FunctionsHttpError, SupabaseClient } from '@supabase/supabase-js';
import { Database } from 'supabase/types/supabase';
import { Verse } from '../verse/verse';
import { BibleId } from 'supabase/functions/_shared/bibles';

// TODO BG break this up into smaller services
@Injectable({
  providedIn: 'root',
})
export class SupabaseService {
  private supabaseClient = inject<SupabaseClient<Database>>(SupabaseClient);


  get session() {
    return this.supabaseClient.auth
      .getSession()
      .then(({ data }) => data?.session);
  }


  getSearches() {
    return this.supabaseClient.functions
      .invoke('search', {
        method: 'GET',
      })
      .then(({ data, error }) => ({ results: data?.verses as Verse[], error }));
  }

  get verses() {
    return this.supabaseClient.functions
      .invoke('verses', {
        method: 'GET',
      })
      .then(({ data, error }) => ({ results: data?.verses as Verse[], error }));
  }

  async searchVerses(
    bible_id: BibleId,
    book: string,
    chapter: number,
    start_verse: number,
    end_verse?: number
  ) {
    return this.invokeSearchVersesFunction(
      bible_id,
      book,
      chapter,
      start_verse,
      end_verse,
      'search'
    );
  }

  async searchPublicVerses(
    bible_id: BibleId,
    book: string,
    chapter: number,
    start_verse: number,
    end_verse?: number
  ) {
    return this.invokeSearchVersesFunction(
      bible_id,
      book,
      chapter,
      start_verse,
      end_verse,
      'public'
    );
  }

  private async invokeSearchVersesFunction(
    bible_id: BibleId,
    book: string,
    chapter: number,
    start_verse: number,
    end_verse?: number,
    functionName: 'search' | 'public' = 'search'
  ) {
    // TODO BG types
    return this.supabaseClient.functions
      .invoke(functionName, {
        body: {
          search: {
            bible_id,
            book,
            chapter,
            start_verse,
            end_verse,
          },
        },
        method: 'POST',
      })
      .then(async ({ data, error }) => {
        if (error instanceof FunctionsHttpError) {
          const response = await error.context.json();
          const defaultError =
            'Oops! An error has occurred - please send a screenshot to bobby@workingdevshero.com';
          return {
            results: [] as Verse[],
            error: response.error || defaultError,
          };
        }
        return {
          results: data?.verse ? [data.verse] : ([] as Verse[]),
          error: data.error,
        };
      }); // TODO BG types
  }

  async updateVerse(
    verse: Omit<Verse, 'created_at' | 'last_updated' | 'user_id'>
  ) {
    return this.supabaseClient.functions
      .invoke(`verses/${verse.id}`, {
        body: { verse },
        method: 'PUT',
      })
      .then(({ data }) => data.verse as Verse); // TODO BG types
  }
}
