import { CommonModule } from '@angular/common';
import {
  Component,
  Input,
  OnInit,
  inject,
  signal,
  computed,
} from '@angular/core';
import { FormsModule } from '@angular/forms';
import {
  AlertController,
  IonButton,
  IonButtons,
  IonCheckbox,
  IonContent,
  IonHeader,
  IonIcon,
  IonInput,
  IonItem,
  IonItemOption,
  IonItemOptions,
  IonItemSliding,
  IonLabel,
  IonList,
  IonSpinner,
  IonTitle,
  IonToolbar,
  ModalController,
} from '@ionic/angular/standalone';
import { addIcons } from 'ionicons';
import { addOutline, chevronBack, closeOutline, trashOutline } from 'ionicons/icons';
import { Tag } from '../verse/verse';
import { TagsService } from '../../tags/tags.service';

interface TagWithSelected extends Tag {
  selected: boolean;
}

@Component({
  selector: 'app-tag-popup',
  templateUrl: './tag-popup.component.html',
  styleUrls: ['./tag-popup.component.scss'],
  imports: [
    CommonModule,
    FormsModule,
    IonHeader,
    IonToolbar,
    IonTitle,
    IonButtons,
    IonButton,
    IonContent,
    IonIcon,
    IonList,
    IonItem,
    IonItemSliding,
    IonItemOptions,
    IonItemOption,
    IonLabel,
    IonCheckbox,
    IonInput,
    IonSpinner,
  ],
})
export class TagPopupComponent implements OnInit {
  @Input({ required: true }) verseId!: number;

  private modalCtrl = inject(ModalController);
  private alertCtrl = inject(AlertController);
  private tagsService = inject(TagsService);

  isLoading = signal(true);
  tags = signal<TagWithSelected[]>([]);
  newTagName = signal('');
  newTagColor = signal('#6366f1');
  isCreatingTag = signal(false);
  showColorPicker = signal(false);
  editingTagColor: number | null = null;

  // Predefined color palette
  readonly colorPalette = [
    '#6366f1', // indigo
    '#8b5cf6', // purple
    '#ec4899', // pink
    '#f43f5e', // rose
    '#ef4444', // red
    '#f97316', // orange
    '#f59e0b', // amber
    '#eab308', // yellow
    '#84cc16', // lime
    '#22c55e', // green
    '#10b981', // emerald
    '#14b8a6', // teal
    '#06b6d4', // cyan
    '#3b82f6', // blue
    '#0ea5e9', // sky
  ];

  // Track which tags were originally selected vs current state
  private originalSelectedIds = new Set<number>();
  // Track original tag colors
  private originalColors = new Map<number, string>();

  // Computed to check if there are changes
  hasChanges = computed(() => {
    const currentTags = this.tags();
    const currentSelectedIds = new Set(
      currentTags
        .filter((t) => t.selected)
        .map((t) => t.id)
    );

    // Check selection changes
    if (currentSelectedIds.size !== this.originalSelectedIds.size) {
      return true;
    }

    for (const id of currentSelectedIds) {
      if (!this.originalSelectedIds.has(id)) {
        return true;
      }
    }

    // Check color changes
    for (const tag of currentTags) {
      const originalColor = this.originalColors.get(tag.id);
      const currentColor = tag.color || '#6366f1';
      if (originalColor && currentColor !== originalColor) {
        return true;
      }
    }

    return false;
  });

  constructor() {
    addIcons({ chevronBack, addOutline, trashOutline, closeOutline });
  }

  async ngOnInit() {
    await this.loadTags();
  }

  private async loadTags() {
    this.isLoading.set(true);

    try {
      // Load all user tags and verse tags in parallel
      const [allTags, verseTags] = await Promise.all([
        this.tagsService.getUserTags(),
        this.tagsService.getVerseTags(this.verseId),
      ]);

      const verseTagIds = new Set(verseTags.map((t) => t.id));

      // Merge with selected state
      const tagsWithSelected: TagWithSelected[] = allTags.map((tag) => ({
        ...tag,
        selected: verseTagIds.has(tag.id),
      }));

      this.tags.set(tagsWithSelected);

      // Store original state for change detection
      this.originalSelectedIds = new Set(
        tagsWithSelected.filter((t) => t.selected).map((t) => t.id)
      );
      this.originalColors = new Map(
        tagsWithSelected.map((t) => [t.id, t.color || '#6366f1'])
      );
    } finally {
      this.isLoading.set(false);
    }
  }

  async dismiss() {
    await this.modalCtrl.dismiss();
  }

  toggleColorPicker() {
    this.showColorPicker.set(!this.showColorPicker());
  }

  async save() {
    const currentTags = this.tags();
    const addedTags: number[] = [];
    const removedTags: number[] = [];
    const colorChanges: { id: number; color: string }[] = [];

    for (const tag of currentTags) {
      const wasSelected = this.originalSelectedIds.has(tag.id);
      if (tag.selected && !wasSelected) {
        addedTags.push(tag.id);
      } else if (!tag.selected && wasSelected) {
        removedTags.push(tag.id);
      }

      // Check for color changes
      const originalColor = this.originalColors.get(tag.id);
      const currentColor = tag.color || '#6366f1';
      if (originalColor && currentColor !== originalColor) {
        colorChanges.push({ id: tag.id, color: currentColor });
      }
    }

    // Apply changes
    const promises: Promise<unknown>[] = [];

    for (const tagId of addedTags) {
      promises.push(this.tagsService.addTagToVerse(this.verseId, tagId));
    }

    for (const tagId of removedTags) {
      promises.push(this.tagsService.removeTagFromVerse(this.verseId, tagId));
    }

    for (const { id, color } of colorChanges) {
      promises.push(this.tagsService.updateTag(id, { color }));
    }

    await Promise.all(promises);

    await this.modalCtrl.dismiss({ changed: true });
  }

  toggleTag(tag: TagWithSelected) {
    const updatedTags = this.tags().map((t) =>
      t.id === tag.id ? { ...t, selected: !t.selected } : t
    );
    this.tags.set(updatedTags);
  }

  async createNewTag() {
    const name = this.newTagName().trim();
    if (!name) {
      return;
    }

    this.isCreatingTag.set(true);

    try {
      const newTag = await this.tagsService.createTag(
        name,
        this.newTagColor()
      );
      if (newTag) {
        // Add the new tag to the list and select it
        this.tags.update((tags) => [
          ...tags,
          { ...newTag, selected: true },
        ]);
        this.newTagName.set('');
        this.newTagColor.set('#6366f1'); // Reset to default
      }
    } finally {
      this.isCreatingTag.set(false);
    }
  }

  updateTagColor(tag: TagWithSelected, color: string) {
    this.tags.update((tags) =>
      tags.map((t) => (t.id === tag.id ? { ...t, color } : t))
    );
    this.editingTagColor = null;
  }

  startEditingTagColor(tag: TagWithSelected, event: Event) {
    event.stopPropagation();
    this.editingTagColor = tag.id;
  }

  cancelEditingColor() {
    this.editingTagColor = null;
  }

  async confirmDeleteTag(tag: TagWithSelected, slidingItem: IonItemSliding) {
    const alert = await this.alertCtrl.create({
      header: 'Delete Tag',
      message: `Are you sure you want to delete "${tag.name}"? This will remove the tag from all verses.`,
      buttons: [
        {
          text: 'Cancel',
          role: 'cancel',
          handler: () => {
            slidingItem.close();
          },
        },
        {
          text: 'Delete',
          role: 'destructive',
          handler: async () => {
            await this.deleteTag(tag);
            slidingItem.close();
          },
        },
      ],
    });

    await alert.present();
  }

  getTagColor(tag: Tag): string {
    return tag.color || '#6366f1';
  }

  private async deleteTag(tag: TagWithSelected) {
    const deleted = await this.tagsService.deleteTag(tag.id);
    if (deleted) {
      const wasSelected = this.originalSelectedIds.has(tag.id);
      this.tags.update((tags) => tags.filter((t) => t.id !== tag.id));
      this.originalSelectedIds.delete(tag.id);
      
      // Always dismiss with changed: true when a tag is deleted
      // so the parent component refreshes the tags display
      // (the tag list has changed, and if it was selected, the verse's tags need updating)
      await this.modalCtrl.dismiss({ changed: true });
    }
  }
}


