import {
  Component,
  computed,
  inject,
  Injector,
  input,
  output,
  signal,
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterLink, UrlTree } from '@angular/router';
import {
  IonAlert,
  IonButton,
  IonCard,
  IonCardContent,
  IonCardHeader,
  IonCardSubtitle,
  IonCardTitle,
  IonRouterLink,
  LoadingController,
  ModalController,
} from '@ionic/angular/standalone';
import { MarkdownModule } from 'ngx-markdown';
import { BibleId, bibles } from 'supabase/functions/_shared/bibles';
import { SupabaseService } from '../../supabase/supabase.service';
import { TagPopupComponent } from '../../tag-popup/tag-popup.component';
import { TagChipComponent } from '../../tag-chip/tag-chip.component';
import { TagsService } from '../../../tags/tags.service';
import { FavoritesService } from '../../../favorites/favorites.service';
import { Tag } from '../verse';

@Component({
  selector: 'app-verse-card',
  templateUrl: './verse-card.component.html',
  styleUrls: ['./verse-card.component.scss'],
  imports: [
    CommonModule,
    IonCardSubtitle,
    IonAlert,
    IonButton,
    IonCard,
    IonCardHeader,
    IonCardTitle,
    IonCardContent,
    MarkdownModule,
    RouterLink,
    IonRouterLink,
    TagChipComponent,
  ],
})
export class VerseCardComponent {
  private loadingCtrl = inject(LoadingController);
  private modalCtrl = inject(ModalController);
  private supabaseService = inject(SupabaseService);
  private tagsService = inject(TagsService);
  private favoritesService = inject(FavoritesService);

  icons = {
    heartFilled: 'node_modules/openmoji/color/svg/2764.svg', // ❤️ Red Heart
    heartOutline: 'node_modules/openmoji/color/svg/1F90D.svg', // 🤍 White Heart
    tagFilled: 'node_modules/openmoji/color/svg/1F3F7.svg', // 🏷️ Label (filled)
    tagOutline: 'node_modules/openmoji/color/svg/1F3F7.svg', // 🏷️ Label (same icon, we'll use opacity)
  };

  // Signal inputs
  id = input.required<number>();
  bibleId = input.required<BibleId>();
  book = input.required<string>();
  chapter = input.required<number>();
  startVerse = input.required<number>();
  endVerse = input.required<number>();
  content = input.required<string>();
  isFavorite = input.required<boolean>();
  hideFavoriteButton = input<boolean>(false);
  hideTagButton = input<boolean>(false);
  tagCount = input<number>(0);
  tags = input<Tag[]>([]); // Optional tags array for displaying tags at bottom
  showTagsAtBottom = input<boolean>(false); // Control whether to show tags at bottom
  routerLink = input<string | any[] | UrlTree | null | undefined>();

  // Signal outputs
  favoriteRemoved = output<void>();
  tagsChanged = output<void>();
  tagClicked = output<Tag>();

  // Internal signals
  private _isFavoriteOverride = signal<boolean | null>(null);
  private _tagCountOverride = signal<number | null>(null);
  removeFavoriteAlertIsOpen = signal<boolean>(false);

  // Computed signals
  title = computed(() => {
    const start = this.startVerse();
    const end = this.endVerse();
    return `${this.book()} ${this.chapter()}:${start}${
      end !== start ? `-${end}` : ''
    }`;
  });

  subtitle = computed(() => {
    return bibles.get(this.bibleId())?.name;
  });

  // Computed signal for current favorite state
  currentIsFavorite = computed(() => {
    // Use internal override if it has been set, otherwise use input
    const override = this._isFavoriteOverride();
    return override !== null ? override : this.isFavorite();
  });

  // Computed signal for current tag count
  currentTagCount = computed(() => {
    const override = this._tagCountOverride();
    return override !== null ? override : this.tagCount();
  });

  // Computed signal to check if verse has tags
  hasTags = computed(() => this.currentTagCount() > 0);

  onTagChipClick(tag: Tag) {
    this.tagClicked.emit(tag);
  }

  alertButtons = [
    {
      text: 'Cancel',
      role: 'cancel',
    },
    {
      text: 'OK',
      role: 'confirm',
      handler: async () => this.removeFavorite(),
    },
  ];

  async favoriteClick(event: Event) {
    event.preventDefault();
    event.stopPropagation();
    if (this.currentIsFavorite()) {
      this.removeFavoriteAlertIsOpen.set(true);
      return;
    }

    return this.addFavorite();
  }

  async tagClick(event: Event) {
    event.preventDefault();
    event.stopPropagation();

    const modal = await this.modalCtrl.create({
      component: TagPopupComponent,
      componentProps: {
        verseId: this.id(),
      },
    });

    await modal.present();

    const { data } = await modal.onDidDismiss();

    if (data?.changed) {
      // Refresh tag count
      const tags = await this.tagsService.getVerseTags(this.id());
      this._tagCountOverride.set(tags.length);

      // If tags were added, the verse is now favorited
      if (tags.length > 0) {
        this._isFavoriteOverride.set(true);
      }

      this.tagsChanged.emit();
    }
  }

  private async addFavorite() {
    this._isFavoriteOverride.set(true);
    await this.supabaseService.updateVerse({
      id: this.id(),
      bible_id: this.bibleId(),
      book: this.book(),
      chapter: this.chapter(),
      start_verse: this.startVerse(),
      end_verse: this.endVerse(),
      content: this.content(),
      is_favorite: true,
    });
    // Sync to widget after adding favorite
    this.favoritesService.syncToWidget();
  }

  private async removeFavorite() {
    this._isFavoriteOverride.set(false);
    const loading = await this.loadingCtrl.create();
    await loading.present();
    await this.supabaseService.updateVerse({
      id: this.id(),
      bible_id: this.bibleId(),
      book: this.book(),
      chapter: this.chapter(),
      start_verse: this.startVerse(),
      end_verse: this.endVerse(),
      content: this.content(),
      is_favorite: false,
    });
    await loading.dismiss();
    // Sync to widget after removing favorite
    this.favoritesService.syncToWidget();
    this.favoriteRemoved.emit();
  }
}
