const _bibles: BibleReference[] = [
  // From https://api.scripture.api.bible/v1/bibles?language=eng&include-full-details=false
  {
    id: 'de4e12af7f28f599-02',
    name: 'King James Version',
    abbreviation: 'engKJV',
    description: 'Protestant',
    source: 'api.bible',
  },
  {
    id: 'private-bible-csb',
    name: 'Christian Standard Bible',
    abbreviation: 'csb',
    description: 'Protestant',
    source: 'private',
  },
  {
    id: 'private-bible-esv',
    name: 'English Standard Version',
    abbreviation: 'esv',
    description: 'Protestant',
    source: 'private',
  },
];

export const bibles = new Map(_bibles.map((b) => [b.id, b]));
// ESV is the default Bible version
export const defaultBible = _bibles.find((b) => b.id === 'private-bible-esv') || _bibles[0];

export type BibleId =
  | 'private-bible-csb'
  | 'private-bible-esv'
  | 'de4e12af7f28f599-02';

export type BibleReference = {
  id: BibleId;
  name: string;
  abbreviation: string;
  description: string;
  source: BibleSource;
};

export type BibleSource = 'private' | 'api.bible';
